extends Node3D
## A6 Effect A frame-strip preview (CHANGE-BRIEF §E). FIXTURE: loads the real slice (level art, sky, string lights,
## Hari, the in-game camera rig), holds the clock at 10:00 PM, stands Hari still at the dark gate or under the warm
## bulbs, hides the HUD, and spawns a FootstepScuff at Hari's floor position on frame 10 (and frame 21 with
## `retrigger`). The scuff's particles use a fixed seed here only, so before/after strips are comparable; the effect
## scene itself never sets one (repeats in play must vary).

const SLICE := preload("res://scenes/slice.tscn")
const SCUFF := preload("res://effects/footstep_scuff.tscn")
const HARI_DARK_GATE := Vector3(3.5, 0.0, 1.0)   # §0: the darkest stretch is the gate end (x < 5)
const HARI_UNDER_BULBS := Vector3(12.0, 0.0, 1.0) # §0: under the string lights, middle span
const HELD_CLOCK := 22 * 60                       # 10:00 PM, the A5 judging time; no timeline event before 1:20 AM
const TRIGGER_FRAME_FIRST := 10
const TRIGGER_FRAME_SECOND := 21                  # §E, 11 frames after the first (one real step at 30 fps)
const PREVIEW_SEED := 6

@export var lit: bool = false                     # false = dark gate, true = under the warm string lights
@export var retrigger: bool = false               # on = a second scuff at frame 21 while the first is still alive

var slice: Node3D
var _frame := 0

func _ready() -> void:
	var args := OS.get_cmdline_user_args()          # capture variants: godot ... -- lit retrigger
	lit = lit or "lit" in args
	retrigger = retrigger or "retrigger" in args
	slice = SLICE.instantiate()
	add_child(slice)                              # slice._ready() starts loop 1 at 8:00 PM
	LoopState.test_hold_clock = true
	LoopState.test_advance_to(HELD_CLOCK)
	slice.get_node("HUD").visible = false
	var hari: CharacterBody3D = slice.get_node("Hari")
	hari.position = HARI_UNDER_BULBS if lit else HARI_DARK_GATE
	hari.reset_physics_interpolation()
	slice.get_node("CameraRig").snap()

func _process(_delta: float) -> void:
	_frame += 1
	if _frame == TRIGGER_FRAME_FIRST or (retrigger and _frame == TRIGGER_FRAME_SECOND):
		_spawn_scuff()

func _spawn_scuff() -> void:
	var inst: Node3D = SCUFF.instantiate()
	for child in inst.get_children():
		(child as CPUParticles3D).use_fixed_seed = true
		(child as CPUParticles3D).seed = PREVIEW_SEED
	var hari: Node3D = slice.get_node("Hari")
	inst.position = Vector3(hari.global_position.x, 0.0, hari.global_position.z)
	slice.add_child(inst)
	for child in inst.get_children():
		(child as CPUParticles3D).emitting = true

extends Node3D
## Builds the simple-box set dressing: railing, pool walls, string-light poles, bulbs and lights.
## Layout numbers (metres) are constants here; the floor and water are textured nodes in the scene.

const Art3D = preload("res://scenes/art3d.gd")
const DECK_LENGTH := 26.0
const DECK_HALF_DEPTH := 4.0
const RAILING_START_X := 20.0
const POOL := Rect2(9.0, -3.2, 7.0, 2.4)      ## x, z, size x, size z (the recess)
const POOL_DEPTH := 0.6
const LIGHT_XS := [6.0, 10.0, 14.0, 18.0]      ## string-light poles along the back of the deck
const LIGHT_Z := -3.6
const STRING_LIGHT_COLOR := Color(1.0, 0.66, 0.36)   ## ~2700 K

func _ready() -> void:
	var rail := Art3D.lit_material(Color("d8cbb5"))
	# railing along the +x end and along +z for the railing zone
	_box(Vector3(0.08, 0.08, DECK_HALF_DEPTH * 2), Vector3(DECK_LENGTH, 1.05, 0), rail)
	_box(Vector3(DECK_LENGTH - RAILING_START_X, 0.08, 0.08), Vector3((DECK_LENGTH + RAILING_START_X) / 2.0, 1.05, DECK_HALF_DEPTH), rail)
	for i in 9:
		_box(Vector3(0.06, 1.05, 0.06), Vector3(DECK_LENGTH, 0.52, -DECK_HALF_DEPTH + i * 1.0), rail)
	for i in 7:
		_box(Vector3(0.06, 1.05, 0.06), Vector3(RAILING_START_X + i * 1.0, 0.52, DECK_HALF_DEPTH), rail)
	# pool walls (the floor has a hole over POOL; water sits below)
	var tile := Art3D.lit_material(Color("8fd3e0"))
	var c := POOL.get_center()
	_box(Vector3(POOL.size.x, POOL_DEPTH, 0.05), Vector3(c.x, -POOL_DEPTH / 2, POOL.position.y), tile)
	_box(Vector3(POOL.size.x, POOL_DEPTH, 0.05), Vector3(c.x, -POOL_DEPTH / 2, POOL.end.y), tile)
	_box(Vector3(0.05, POOL_DEPTH, POOL.size.y), Vector3(POOL.position.x, -POOL_DEPTH / 2, c.y), tile)
	_box(Vector3(0.05, POOL_DEPTH, POOL.size.y), Vector3(POOL.end.x, -POOL_DEPTH / 2, c.y), tile)
	# string lights: poles, a sagging row of emissive bulbs, and a warm OmniLight3D per span
	var pole := Art3D.lit_material(Color("2b2530"))
	var bulb := Art3D.lit_material(Color("ffd36b"), 4.0, Color("ffc46b"))
	for i in LIGHT_XS.size():
		var x: float = LIGHT_XS[i]
		_box(Vector3(0.08, 3.2, 0.08), Vector3(x, 1.6, LIGHT_Z), pole)
		if i + 1 < LIGHT_XS.size():
			var next: float = LIGHT_XS[i + 1]
			for s in range(1, 8):
				var t := s / 8.0
				_sphere(0.06, Vector3(lerpf(x, next, t), 3.1 - sin(t * PI) * 0.45, LIGHT_Z + 0.05), bulb)
			var light := OmniLight3D.new()
			light.light_color = STRING_LIGHT_COLOR
			light.light_energy = 2.8
			light.omni_range = 7.0
			light.position = Vector3((x + next) / 2.0, 2.7, LIGHT_Z + 1.2)
			add_child(light)

func _box(size: Vector3, pos: Vector3, material: Material) -> void:
	var mi := MeshInstance3D.new()
	var mesh := BoxMesh.new()
	mesh.size = size
	mi.mesh = mesh
	mi.position = pos
	mi.material_override = material
	add_child(mi)

func _sphere(radius: float, pos: Vector3, material: Material) -> void:
	var mi := MeshInstance3D.new()
	var mesh := SphereMesh.new()
	mesh.radius = radius
	mesh.height = radius * 2.0
	mesh.radial_segments = 8
	mesh.rings = 4
	mi.mesh = mesh
	mi.position = pos
	mi.material_override = material
	add_child(mi)

## Writes the hint-experiment texture (CHANGE-BRIEF.md §2.5): a 3×1 PNG of greys 64, 128, 192.
## Imported Lossless with no mipmaps, so the shader samples exactly these bytes.
##   godot --headless --path godot -s res://tools/write_hint_strip.gd
extends SceneTree

const OUT := "res://assets/textures/hint_strip_3x1.png"
const GREYS := [64, 128, 192]

func _initialize() -> void:
	var img := Image.create(GREYS.size(), 1, false, Image.FORMAT_RGB8)
	for x in GREYS.size():
		img.set_pixel(x, 0, Color8(GREYS[x], GREYS[x], GREYS[x]))
	var err := img.save_png(OUT)
	var back := Image.load_from_file(ProjectSettings.globalize_path(OUT))
	var read := []
	for x in back.get_width():
		read.append(back.get_pixel(x, 0).r8)
	print("wrote %s: %s (err %d), read back %s" % [OUT, GREYS, err, read])
	quit(0 if err == OK and read == GREYS else 1)

extends Node3D
## Telltale-style follow camera: damped follow of Hari with per-zone framing presets
## blended smoothly by Hari's x. Presets are data: offset from Hari, look-at offset, FOV.

const PRESETS := {
	"gate": {"offset": Vector3(2.4, 2.0, 3.1), "look": Vector3(-0.6, 1.1, -1.8), "fov": 54.0},     # on the deck, looking at the SUV and villa (playtest 3: the old preset sat off the deck and framed the wall)
	"deck": {"offset": Vector3(0.0, 1.9, 4.5), "look": Vector3(0.0, 1.25, 0.0), "fov": 45.0},      # medium
	"railing": {"offset": Vector3(-2.6, 1.8, -2.6), "look": Vector3(2.6, 1.0, 3.2), "fov": 50.0},  # swings past Hari to the sea
}
const GATE_END_X := 5.0
const RAILING_START_X := 20.0
const BLEND_HALF_WIDTH := 1.5           ## m either side of a zone boundary
const FOLLOW_SHARPNESS := 4.5           ## higher = snappier damping
const CAMERA_Z_RANGE := Vector2(-5.5, 9.0)

@export var target_path: NodePath
var target: Node3D
var shake := 0.0                         ## seconds of shake left
var _look := Vector3.ZERO
@onready var camera: Camera3D = $Camera

func _ready() -> void:
	target = get_node(target_path)
	snap()

## Blend weights for the three presets at x.
static func zone_weights(x: float) -> Dictionary:
	var to_deck := smoothstep(GATE_END_X - BLEND_HALF_WIDTH, GATE_END_X + BLEND_HALF_WIDTH, x)
	var to_rail := smoothstep(RAILING_START_X - BLEND_HALF_WIDTH, RAILING_START_X + BLEND_HALF_WIDTH, x)
	return {"gate": 1.0 - to_deck, "deck": to_deck * (1.0 - to_rail), "railing": to_rail}

func _target_pos() -> Vector3:
	return target.get_global_transform_interpolated().origin   # physics interpolation: smooth at any display rate

func desired() -> Array:
	var tp := _target_pos()
	var weights := zone_weights(tp.x)
	var offset := Vector3.ZERO
	var look := Vector3.ZERO
	var fov := 0.0
	for zone in weights:
		offset += PRESETS[zone].offset * weights[zone]
		look += PRESETS[zone].look * weights[zone]
		fov += PRESETS[zone].fov * weights[zone]
	var pos: Vector3 = tp + offset
	pos.z = clampf(pos.z, CAMERA_Z_RANGE.x, CAMERA_Z_RANGE.y)
	return [pos, tp + look, fov]

func snap() -> void:
	var d := desired()
	camera.global_position = d[0]
	_look = d[1]
	camera.fov = d[2]
	camera.look_at(_look)

func _process(delta: float) -> void:
	var d := desired()
	var k := 1.0 - exp(-FOLLOW_SHARPNESS * delta)
	camera.global_position = camera.global_position.lerp(d[0], k)
	_look = _look.lerp(d[1], k)
	camera.fov = lerpf(camera.fov, d[2], k)
	camera.look_at(_look)
	shake = maxf(shake - delta, 0.0)
	if shake > 0.0:
		var a := 0.08 * shake
		camera.global_position += Vector3(randf_range(-a, a), randf_range(-a, a), 0.0)

