## Writes the moth silhouette PNG used by Effect B's particles (CHANGE-BRIEF §B.3,
## "The moth texture should have two simple wings and a small darker centre. It can
## be generated with a short GDScript and committed with its source"). The PNG sits
## next to the effect scene, so the scene can reference it with an ext_resource.
## The particle material sets vertex_color_use_as_albedo = true, so the ramp's pale
## cream multiplies the texture's grayscale: wings read as cream, the body stays a
## muted brown (grayscale 0.32 here, so cream × 0.32 ≈ a dark brown dot).
##   godot --headless --path godot -s res://tools/write_moth_texture.gd
extends SceneTree

const OUT := "res://effects/moth.png"
const W := 64
const H := 40                                  ## matches the 0.07 × 0.045 m quad ratio

func _initialize() -> void:
	var img := Image.create(W, H, false, Image.FORMAT_RGBA8)
	for y in H:
		for x in W:
			var nx := (float(x) + 0.5 - W * 0.5) / (W * 0.5)
			var ny := (float(y) + 0.5 - H * 0.5) / (H * 0.5)
			var left_dx := nx + 0.42
			var right_dx := nx - 0.42
			var wy := ny - 0.05                 ## wings sit a touch above the midline
			var left_d := sqrt(left_dx * left_dx * 6.0 + wy * wy * 3.2)
			var right_d := sqrt(right_dx * right_dx * 6.0 + wy * wy * 3.2)
			var wing_mask := clampf(1.0 - minf(left_d, right_d), 0.0, 1.0)
			wing_mask = wing_mask * wing_mask
			var body_d := sqrt(nx * nx * 70.0 + ny * ny * 5.5)
			var body_mask := clampf(1.0 - body_d, 0.0, 1.0)
			var alpha := clampf(wing_mask + body_mask, 0.0, 1.0)
			if alpha <= 0.02:
				img.set_pixel(x, y, Color(0, 0, 0, 0))
				continue
			var body_w := body_mask / (body_mask + wing_mask + 0.0001)
			var gray := lerpf(1.0, 0.32, body_w)
			img.set_pixel(x, y, Color(gray, gray, gray, alpha))
	var err := img.save_png(ProjectSettings.globalize_path(OUT))
	print("wrote %s: %dx%d (err %d)" % [OUT, W, H, err])
	quit(0 if err == OK else 1)

